import com.kongye.floatball.GestureRules;
public class EdgeGapCheck {public static void main(String[] args){if(GestureRules.edgeWithInset(0,1080,126,32)!=32)throw new AssertionError("left gap");if(GestureRules.edgeWithInset(954,1080,126,32)!=922)throw new AssertionError("right gap");if(GestureRules.edgeWithInset(954,1080,394,0)!=686)throw new AssertionError("150dp ball");if(GestureRules.edgeWithInset(0,100,60,1000)!=20)throw new AssertionError("oversized positive gap clamp");if(GestureRules.edgeWithInset(0,1080,126,-1)!=-1)throw new AssertionError("negative left gap");if(GestureRules.edgeWithInset(954,1080,126,-263)!=1217)throw new AssertionError("negative right gap");if(GestureRules.edgeWithInset(-100,1080,394,-263)!=-263)throw new AssertionError("partly offscreen 150dp ball");if(GestureRules.edgeWithInset(954,1080,394,-263)!=949)throw new AssertionError("large right ball partially covered");System.out.println("8 edge inset checks passed.");}}
